/* From Uiverse.io by vinodjangid07 - Tags: instagram, button, hover effect */
.__UIV_SCOPE__ .Btn {
  border: none;
  border-radius: 50%;
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition-duration: .4s;
  cursor: pointer;
  position: relative;
  background: #f09433;
  background: -moz-linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%);
  background: -webkit-linear-gradient(45deg, #f09433 0%,#e6683c 25%,#dc2743 50%,#cc2366 75%,#bc1888 100%);
  background: linear-gradient(45deg, #f09433 0%,#e6683c 25%,#dc2743 50%,#cc2366 75%,#bc1888 100%);
  filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#f09433', endColorstr='#bc1888',GradientType=1 );
  overflow: hidden;
}

.__UIV_SCOPE__ .svgIcon {
  transition-duration: .3s;
}

.__UIV_SCOPE__ .svgIcon path {
  fill: white;
}

.__UIV_SCOPE__ .text {
  position: absolute;
  color: rgb(255, 255, 255);
  width: 120px;
  font-weight: 600;
  opacity: 0;
  transition-duration: .4s;
}

.__UIV_SCOPE__ .Btn:hover {
  width: 110px;
  transition-duration: .4s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .Btn:hover .text {
  opacity: 1;
  transition-duration: .4s;
}

.__UIV_SCOPE__ .Btn:hover .svgIcon {
  opacity: 0;
  transition-duration: .3s;
}
